mapper.select:
SELECT * FROM message
WHERE is_deleted = 0


      AND conversation_type = 0
      AND ((from_user_id = #{userId} AND to_id = #{targetId})
           OR (from_user_id = #{targetId} AND to_id = #{userId}))


      AND conversation_type = #{type}
      AND conversation_id = #{conversationId}


ORDER BY send_time DESC, seq DESC
LIMIT #{limit}

SELECT * FROM message
WHERE send_time < #{cursorTime}
  AND is_deleted = 0


      AND conversation_type = 0
      AND ((from_user_id = #{userId} AND to_id = #{targetId})
           OR (from_user_id = #{targetId} AND to_id = #{userId}))


      AND conversation_type = #{type}
      AND conversation_id = #{conversationId}


ORDER BY send_time DESC, seq DESC
LIMIT #{limit}

SELECT * FROM message
WHERE send_time > #{cursorTime}
  AND is_deleted = 0


      AND conversation_type = 0
      AND ((from_user_id = #{userId} AND to_id = #{targetId})
           OR (from_user_id = #{targetId} AND to_id = #{userId}))


      AND conversation_type = #{type}
      AND conversation_id = #{conversationId}


ORDER BY seq ASC
LIMIT #{limit}
